<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Ubuntu-Inspired Desktop</title>
  <style>
    :root {
      --bg: #191724;
      --panel: rgba(35, 32, 47, 0.92);
      --window: #2a2738;
      --window-deep: #211f2c;
      --border: #4b465f;
      --text: #f5f2fa;
      --muted: #b8b2c8;
      --accent: #ff7a3d;
      --accent-soft: #d95f27;
      --purple: #7e5bef;
      --shadow: 0 18px 45px rgba(0, 0, 0, 0.45);
    }

    * {
      box-sizing: border-box;
    }

    html,
    body {
      width: 100%;
      height: 100%;
      margin: 0;
      overflow: hidden;
      font-family: Arial, Helvetica, sans-serif;
      color: var(--text);
      background: #171421;
    }

    button,
    textarea {
      font: inherit;
    }

    button {
      cursor: pointer;
    }

    #desktop {
      position: relative;
      width: 100vw;
      height: 100vh;
      overflow: hidden;
      background:
        radial-gradient(circle at 78% 24%, rgba(123, 81, 227, 0.48), transparent 25%),
        radial-gradient(circle at 20% 78%, rgba(237, 103, 55, 0.33), transparent 30%),
        linear-gradient(135deg, #19162b 0%, #34224d 42%, #6c3150 100%);
    }

    #desktop::before,
    #desktop::after {
      content: "";
      position: absolute;
      border-radius: 50%;
      pointer-events: none;
      filter: blur(4px);
      opacity: 0.55;
    }

    #desktop::before {
      width: 48vw;
      height: 48vw;
      right: -12vw;
      bottom: -20vw;
      background: rgba(255, 115, 61, 0.28);
    }

    #desktop::after {
      width: 35vw;
      height: 35vw;
      left: -12vw;
      top: 9vh;
      background: rgba(85, 69, 191, 0.34);
    }

    .topbar {
      position: absolute;
      z-index: 50;
      top: 0;
      left: 0;
      width: 100%;
      height: 34px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 14px;
      background: rgba(19, 17, 28, 0.74);
      backdrop-filter: blur(12px);
      font-size: 13px;
      color: #f2eef9;
    }

    .topbar-left,
    .topbar-right {
      display: flex;
      align-items: center;
      gap: 14px;
    }

    .activities {
      font-weight: bold;
    }

    .clock {
      font-variant-numeric: tabular-nums;
    }

    .desktop-icons {
      position: absolute;
      z-index: 1;
      top: 58px;
      left: 22px;
      display: grid;
      gap: 18px;
    }

    .desktop-icon {
      width: 78px;
      text-align: center;
      color: white;
      font-size: 12px;
      text-shadow: 0 1px 4px #000;
    }

    .icon-tile {
      width: 48px;
      height: 48px;
      margin: 0 auto 5px;
      display: grid;
      place-items: center;
      border-radius: 11px;
      background: linear-gradient(145deg, #7b61dc, #3e307b);
      box-shadow: 0 8px 15px rgba(0, 0, 0, 0.24);
      font-size: 25px;
    }

    #taskbar {
      position: absolute;
      z-index: 100;
      left: 50%;
      bottom: 16px;
      transform: translateX(-50%);
      display: flex;
      align-items: center;
      gap: 9px;
      padding: 8px;
      border: 1px solid rgba(255, 255, 255, 0.17);
      border-radius: 18px;
      background: rgba(28, 25, 39, 0.82);
      box-shadow: 0 12px 35px rgba(0, 0, 0, 0.4);
      backdrop-filter: blur(16px);
    }

    .launcher {
      width: 52px;
      height: 52px;
      border: 0;
      border-radius: 13px;
      color: white;
      background: transparent;
      transition: transform 0.16s ease, background 0.16s ease;
      font-size: 25px;
      line-height: 1;
    }

    .launcher:hover,
    .launcher:focus-visible {
      transform: translateY(-4px);
      background: rgba(255, 255, 255, 0.14);
      outline: none;
    }

    #open-files {
      background: linear-gradient(145deg, #f3a53b, #de6929);
    }

    #open-notepad {
      background: linear-gradient(145deg, #846bf1, #5541b0);
    }

    .window {
      position: absolute;
      z-index: 10;
      display: none;
      min-width: 360px;
      min-height: 240px;
      width: 620px;
      height: 430px;
      overflow: hidden;
      border: 1px solid rgba(255, 255, 255, 0.17);
      border-radius: 12px;
      background: var(--window);
      box-shadow: var(--shadow);
      resize: both;
    }

    #files-window {
      top: 82px;
      left: 13vw;
    }

    #notepad-window {
      top: 112px;
      left: 30vw;
      width: 650px;
      height: 455px;
    }

    .window-titlebar {
      height: 43px;
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 0 11px 0 14px;
      user-select: none;
      cursor: grab;
      background: linear-gradient(180deg, #393548, #2c2939);
      border-bottom: 1px solid var(--border);
    }

    .window-titlebar:active {
      cursor: grabbing;
    }

    .window-app-icon {
      font-size: 17px;
    }

    .window-title {
      flex: 1;
      overflow: hidden;
      font-size: 14px;
      font-weight: bold;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .window-controls {
      display: flex;
      gap: 6px;
    }

    .win-control {
      width: 26px;
      height: 26px;
      border: 0;
      border-radius: 7px;
      color: #f7f3ff;
      background: transparent;
      font-size: 17px;
      line-height: 1;
    }

    .win-control:hover {
      background: rgba(255, 255, 255, 0.12);
    }

    .win-close:hover {
      background: #d94a42;
    }

    .window-body {
      height: calc(100% - 43px);
      min-height: 197px;
    }

    .files-body {
      display: flex;
      flex-direction: column;
      background: #252230;
    }

    .file-toolbar {
      display: flex;
      align-items: center;
      gap: 9px;
      min-height: 50px;
      padding: 8px 12px;
      border-bottom: 1px solid var(--border);
      background: #2e2a3c;
    }

    #files-up {
      width: 31px;
      height: 31px;
      border: 0;
      border-radius: 7px;
      color: var(--text);
      background: #423d52;
      font-size: 19px;
    }

    #files-up:hover:not(:disabled) {
      background: #5a526d;
    }

    #files-up:disabled {
      opacity: 0.43;
      cursor: default;
    }

    #files-path {
      flex: 1;
      min-width: 0;
      padding: 7px 10px;
      overflow: hidden;
      border-radius: 6px;
      background: #1c1a25;
      color: #e9e5ef;
      font-family: "Courier New", monospace;
      font-size: 13px;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    #files-list {
      flex: 1;
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(122px, 1fr));
      align-content: start;
      gap: 8px;
      overflow: auto;
      padding: 15px;
    }

    .fs-item {
      min-height: 93px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      padding: 8px;
      overflow: hidden;
      border: 1px solid transparent;
      border-radius: 9px;
      color: #f8f5fb;
      cursor: default;
      text-align: center;
      font-size: 13px;
      word-break: break-word;
    }

    .fs-item:hover {
      border-color: rgba(155, 127, 255, 0.65);
      background: rgba(126, 91, 239, 0.19);
    }

    .fs-symbol {
      font-size: 33px;
      line-height: 1;
    }

    .fs-item.file .fs-symbol {
      font-size: 30px;
    }

    .notepad-body {
      display: flex;
      flex-direction: column;
      background: #211f2d;
    }

    .tabbar {
      display: flex;
      align-items: stretch;
      min-height: 43px;
      overflow-x: auto;
      border-bottom: 1px solid var(--border);
      background: #2b2838;
    }

    #tabs {
      display: flex;
      flex: 1;
      min-width: 0;
    }

    .tab {
      max-width: 170px;
      min-width: 112px;
      padding: 12px 14px;
      overflow: hidden;
      border: 0;
      border-right: 1px solid #49445a;
      color: #c8c1d2;
      background: #302c3d;
      text-align: left;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .tab:hover {
      background: #3b364b;
    }

    .tab.active {
      color: #fff;
      background: #211f2d;
      box-shadow: inset 0 3px 0 var(--accent);
    }

    #new-tab {
      width: 43px;
      flex: 0 0 43px;
      border: 0;
      color: white;
      background: #353143;
      font-size: 22px;
    }

    #new-tab:hover {
      background: #4a4459;
    }

    #editor {
      flex: 1;
      width: 100%;
      min-height: 0;
      padding: 16px;
      resize: none;
      border: 0;
      outline: none;
      color: #f5f2f8;
      background: #211f2d;
      caret-color: var(--accent);
      font-family: "Courier New", monospace;
      font-size: 14px;
      line-height: 1.55;
    }

    @media (max-width: 700px) {
      .window {
        width: calc(100vw - 24px) !important;
        left: 12px !important;
      }

      #files-window {
        top: 48px;
      }

      #notepad-window {
        top: 70px;
      }
    }
  </style>
</head>
<body>
  <main id="desktop" aria-label="Desktop environment">
    <header class="topbar">
      <div class="topbar-left">
        <span class="activities">Activities</span>
        <span>Ubuntu Desktop</span>
      </div>
      <div class="topbar-right">
        <span>◉</span>
        <span>⌁</span>
        <span class="clock" id="clock">12:00</span>
      </div>
    </header>

    <div class="desktop-icons" aria-hidden="true">
      <div class="desktop-icon">
        <div class="icon-tile">⌂</div>
        Home
      </div>
      <div class="desktop-icon">
        <div class="icon-tile">▣</div>
        Computer
      </div>
    </div>

    <section id="files-window" class="window" aria-label="Files window">
      <div class="window-titlebar">
        <span class="window-app-icon">🗀</span>
        <span class="window-title">Files</span>
        <div class="window-controls">
          <button class="win-control win-close" type="button" aria-label="Close Files window">×</button>
        </div>
      </div>
      <div class="window-body files-body">
        <div class="file-toolbar">
          <button id="files-up" type="button" aria-label="Go to parent folder">←</button>
          <div id="files-path" aria-label="Current path">/</div>
        </div>
        <div id="files-list" aria-label="Filesystem listing"></div>
      </div>
    </section>

    <section id="notepad-window" class="window" aria-label="Notepad window">
      <div class="window-titlebar">
        <span class="window-app-icon">📝</span>
        <span class="window-title">Text Editor</span>
        <div class="window-controls">
          <button class="win-control win-close" type="button" aria-label="Close Notepad window">×</button>
        </div>
      </div>
      <div class="window-body notepad-body">
        <div class="tabbar">
          <div id="tabs" role="tablist" aria-label="Open documents"></div>
          <button id="new-tab" type="button" aria-label="New tab" title="New tab">+</button>
        </div>
        <textarea id="editor" aria-label="Text editor" spellcheck="false"></textarea>
      </div>
    </section>

    <nav id="taskbar" aria-label="Application dock">
      <button id="open-files" class="launcher" type="button" aria-label="Open Files" title="Files">🗀</button>
      <button id="open-notepad" class="launcher" type="button" aria-label="Open Notepad" title="Text Editor">📝</button>
    </nav>
  </main>

  <script>
    (() => {
      "use strict";

      let topZ = 20;

      function bringToFront(windowElement) {
        topZ += 1;
        windowElement.style.zIndex = topZ;
      }

      function openWindow(id) {
        const win = document.getElementById(id);
        win.style.display = "block";
        bringToFront(win);
      }

      document.getElementById("open-files").addEventListener("click", () => {
        openWindow("files-window");
      });

      document.getElementById("open-notepad").addEventListener("click", () => {
        openWindow("notepad-window");
      });

      document.querySelectorAll(".win-close").forEach((button) => {
        button.addEventListener("click", () => {
          button.closest(".window").style.display = "none";
        });
      });

      document.querySelectorAll(".window").forEach((win) => {
        win.addEventListener("mousedown", () => bringToFront(win));
      });

      document.querySelectorAll(".window-titlebar").forEach((titlebar) => {
        const win = titlebar.closest(".window");
        let dragging = false;
        let offsetX = 0;
        let offsetY = 0;

        titlebar.addEventListener("mousedown", (event) => {
          if (event.target.closest("button")) return;

          const rect = win.getBoundingClientRect();
          dragging = true;
          offsetX = event.clientX - rect.left;
          offsetY = event.clientY - rect.top;
          bringToFront(win);
          event.preventDefault();
        });

        document.addEventListener("mousemove", (event) => {
          if (!dragging) return;

          const maxLeft = Math.max(0, window.innerWidth - win.offsetWidth);
          const maxTop = Math.max(34, window.innerHeight - win.offsetHeight - 10);
          const left = Math.min(maxLeft, Math.max(0, event.clientX - offsetX));
          const top = Math.min(maxTop, Math.max(34, event.clientY - offsetY));

          win.style.left = left + "px";
          win.style.top = top + "px";
        });

        document.addEventListener("mouseup", () => {
          dragging = false;
        });
      });

      const filesystem = {
        "/": [
          { name: "bin", folder: true },
          { name: "etc", folder: true },
          { name: "home", folder: true },
          { name: "usr", folder: true },
          { name: "var", folder: true },
          { name: "README.txt", folder: false }
        ],
        "/bin": [
          { name: "bash", folder: false },
          { name: "ls", folder: false },
          { name: "python", folder: false }
        ],
        "/etc": [
          { name: "hostname", folder: false },
          { name: "network", folder: true },
          { name: "settings.conf", folder: false }
        ],
        "/etc/network": [
          { name: "interfaces", folder: false }
        ],
        "/home": [
          { name: "user", folder: true }
        ],
        "/home/user": [
          { name: "Documents", folder: true },
          { name: "Downloads", folder: true },
          { name: "Pictures", folder: true },
          { name: "Desktop", folder: true },
          { name: "welcome.txt", folder: false }
        ],
        "/home/user/Documents": [
          { name: "Project Notes.txt", folder: false },
          { name: "Recipes", folder: true },
          { name: "todo.md", folder: false }
        ],
        "/home/user/Documents/Recipes": [
          { name: "pasta.txt", folder: false }
        ],
        "/home/user/Downloads": [
          { name: "ubuntu-wallpaper.jpg", folder: false },
          { name: "archive.zip", folder: false }
        ],
        "/home/user/Pictures": [
          { name: "Mountains.png", folder: false },
          { name: "Sunset.jpg", folder: false }
        ],
        "/home/user/Desktop": [
          { name: "Getting Started.pdf", folder: false }
        ],
        "/usr": [
          { name: "bin", folder: true },
          { name: "share", folder: true },
          { name: "lib", folder: true }
        ],
        "/usr/bin": [
          { name: "nano", folder: false },
          { name: "vim", folder: false }
        ],
        "/usr/share": [
          { name: "applications", folder: true }
        ],
        "/usr/lib": [
          { name: "libexample.so", folder: false }
        ],
        "/var": [
          { name: "log", folder: true },
          { name: "cache", folder: true }
        ],
        "/var/log": [
          { name: "system.log", folder: false }
        ],
        "/var/cache": []
      };

      let currentPath = "/";
      const filesPath = document.getElementById("files-path");
      const filesList = document.getElementById("files-list");
      const filesUp = document.getElementById("files-up");

      function childPath(parent, child) {
        return parent === "/" ? "/" + child : parent + "/" + child;
      }

      function parentPath(path) {
        if (path === "/") return "/";
        const parts = path.split("/").filter(Boolean);
        parts.pop();
        return parts.length ? "/" + parts.join("/") : "/";
      }

      function renderFiles() {
        filesPath.textContent = currentPath;
        filesUp.disabled = currentPath === "/";
        filesList.innerHTML = "";

        const entries = filesystem[currentPath] || [];
        entries.forEach((entry) => {
          const item = document.createElement("div");
          item.className = "fs-item " + (entry.folder ? "folder" : "file");
          item.tabIndex = 0;
          item.innerHTML =
            '<span class="fs-symbol">' + (entry.folder ? "📁" : "📄") + "</span>" +
            "<span>" + entry.name + "</span>";

          if (entry.folder) {
            const navigate = () => {
              currentPath = childPath(currentPath, entry.name);
              renderFiles();
            };
            item.addEventListener("dblclick", navigate);
            item.addEventListener("keydown", (event) => {
              if (event.key === "Enter") navigate();
            });
          }

          filesList.appendChild(item);
        });
      }

      filesUp.addEventListener("click", () => {
        if (currentPath !== "/") {
          currentPath = parentPath(currentPath);
          renderFiles();
        }
      });

      renderFiles();

      const storageKey = "ubuntuDesktopNotepadTabsV1";
      const tabsElement = document.getElementById("tabs");
      const editor = document.getElementById("editor");
      const newTabButton = document.getElementById("new-tab");

      let notebook = {
        activeId: "",
        tabs: []
      };

      function makeId() {
        return "tab-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
      }

      function saveNotebook() {
        try {
          localStorage.setItem(storageKey, JSON.stringify(notebook));
        } catch (error) {
          /* The editor remains usable even if storage is unavailable. */
        }
      }

      function loadNotebook() {
        try {
          const saved = JSON.parse(localStorage.getItem(storageKey));
          if (
            saved &&
            Array.isArray(saved.tabs) &&
            saved.tabs.length &&
            saved.tabs.every((tab) => typeof tab.id === "string" && typeof tab.content === "string")
          ) {
            notebook.tabs = saved.tabs.map((tab, index) => ({
              id: tab.id,
              title: typeof tab.title === "string" ? tab.title : "Untitled " + (index + 1),
              content: tab.content
            }));
            notebook.activeId = notebook.tabs.some((tab) => tab.id === saved.activeId)
              ? saved.activeId
              : notebook.tabs[0].id;
            return;
          }
        } catch (error) {
          /* Start with a clean document when old data is malformed. */
        }

        const firstTab = { id: makeId(), title: "Untitled 1", content: "" };
        notebook.tabs = [firstTab];
        notebook.activeId = firstTab.id;
        saveNotebook();
      }

      function activeTab() {
        return notebook.tabs.find((tab) => tab.id === notebook.activeId) || notebook.tabs[0];
      }

      function renderTabs() {
        tabsElement.innerHTML = "";

        notebook.tabs.forEach((tab) => {
          const button = document.createElement("button");
          button.type = "button";
          button.className = "tab" + (tab.id === notebook.activeId ? " active" : "");
          button.textContent = tab.title;
          button.title = tab.title;
          button.setAttribute("role", "tab");
          button.setAttribute("aria-selected", tab.id === notebook.activeId ? "true" : "false");

          button.addEventListener("click", () => {
            notebook.activeId = tab.id;
            editor.value = tab.content;
            renderTabs();
            saveNotebook();
            editor.focus();
          });

          tabsElement.appendChild(button);
        });

        const selected = activeTab();
        editor.value = selected ? selected.content : "";
      }

      newTabButton.addEventListener("click", () => {
        const tab = {
          id: makeId(),
          title: "Untitled " + (notebook.tabs.length + 1),
          content: ""
        };
        notebook.tabs.push(tab);
        notebook.activeId = tab.id;
        saveNotebook();
        renderTabs();
        editor.focus();
      });

      editor.addEventListener("input", () => {
        const selected = activeTab();
        if (!selected) return;
        selected.content = editor.value;
        saveNotebook();
      });

      loadNotebook();
      renderTabs();

      function updateClock() {
        const now = new Date();
        document.getElementById("clock").textContent = now.toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit"
        });
      }

      updateClock();
      setInterval(updateClock, 1000);
    })();
  </script>
</body>
</html>
